import {UNIVERSITY_LAYOUT} from './modules/university/layout.mjs?v=p21-b407-s039-reuse';
import {createUniversityGraph,universitySnapshot} from './modules/university/core.mjs?v=p21-b407-s039-reuse';
export const UNIVERSITY_GRAPH=createUniversityGraph(UNIVERSITY_LAYOUT);
const copy=v=>JSON.parse(JSON.stringify(v));
export function universityVisitToken(cryptoSource=globalThis.crypto){const bytes=new Uint8Array(16);cryptoSource.getRandomValues(bytes);return [...bytes].map(v=>v.toString(16).padStart(2,"0")).join("");}
export function matchesUniversityMessage(event,{origin,source,session}){return !!session&&event.origin===origin&&event.source===source&&event.data?.session===session&&event.data?.protocol==='cw-university-1';}
export function createUniversityCampaign({makeStore,world,position,visits=()=>[],steps=()=>0,stop=()=>{},restore=()=>{},id=universityVisitToken}){
 const graph=UNIVERSITY_GRAPH,entry=()=>({schema:1,position:UNIVERSITY_LAYOUT.start.slice(),exploredRooms:['GATE']});
 const outside=p=>Array.isArray(p)&&p.length===3&&p.slice(0,2).every(Number.isInteger)&&world.members.get(p.slice(0,2).join(','))?.has(p[2]);
 function read(){const store=makeStore(),value=store.read(),ledger=value.state.flags.universityVisitV1||{schema:1,snapshot:null,active:null};if(ledger.schema!==1||typeof ledger!=='object'||Array.isArray(ledger))throw Error('Unsupported University progress retained without changes');return {store,value,ledger};}
 function door(){const d=world.doors.get('university');if(!d||d.held)throw Error('The University entrance is unavailable');return d;}
 function activeRecord(a){if(!a||a.schema!==1||typeof a.id!=='string'||!a.id||a.doorID!=='university'||!outside(a.returnPosition))throw Error('Saved University return position is unavailable');door();return a;}
 function commit(c){c.value.state.flags.universityVisitV1=c.ledger;c.store.campaign(c.value.state);c.store.project();}
 function enter(){const c=read(),d=door(),p=position();if(c.value.pending)throw Error('Finish the current encounter before entering the University');if(c.value.state.flags.guildInteriorsV1?.active)throw Error('Return from the guildhouse first');if(c.ledger.active)throw Error('A University visit is already active');if(!outside(p)||p[2]!==d.edge||Math.hypot(p[0]-d.position[0],p[1]-d.position[1])>.1)throw Error('Walk to the University entrance first');if(c.ledger.snapshot)universitySnapshot(c.ledger.snapshot,graph);stop();c.store.navigation(p,visits(),steps());const latest=read();latest.ledger.active={schema:1,id:id(),doorID:'university',returnPosition:p.slice()};if(!latest.ledger.snapshot)latest.ledger.snapshot=entry();commit(latest);return active();}
 function active(){const c=read();if(!c.ledger.active)return null;if(c.value.pending||c.value.state.flags.guildInteriorsV1?.active)throw Error('Another encounter or interior visit is active');activeRecord(c.ledger.active);return {...copy(c.ledger.active),snapshot:universitySnapshot(c.ledger.snapshot,graph)};}
 function save(token,snapshot){const c=read(),a=activeRecord(c.ledger.active);if(a.id!==token)throw Error('Stale University visit');const next=universitySnapshot(snapshot,graph),prior=universitySnapshot(c.ledger.snapshot,graph);if(next.position.join(',')!==prior.position.join(',')&&!graph.neighbors(prior.position).some(p=>p.join(',')===next.position.join(',')))throw Object.assign(Error('University movement must follow an open doorway or stair'),{code:'UU_INVALID_TRANSITION'});c.ledger.snapshot=next;commit(c);return copy(next);}
 function finish(token,snapshot){const c=read();if(!c.ledger.active||c.ledger.active.id!==token)return false;const a=activeRecord(c.ledger.active),next=universitySnapshot(snapshot,graph);if(next.position.join(',')!==UNIVERSITY_LAYOUT.start.join(',')||c.ledger.snapshot.position.join(',')!==next.position.join(','))throw Error('Return to the Great Gates before leaving');c.ledger.snapshot=next;c.ledger.active=null;c.store.navigation(a.returnPosition,c.value.visited,c.value.steps);commit(c);restore(a.returnPosition.slice());return true;}
 function cancel(token){const c=read();if(!c.ledger.active||c.ledger.active.id!==token)return false;const a=activeRecord(c.ledger.active);c.ledger.active=null;c.store.navigation(a.returnPosition,c.value.visited,c.value.steps);commit(c);restore(a.returnPosition.slice());return true;}
 return Object.freeze({enter,active,save,finish,cancel,entry,graph});
}
